  FROM tokens.transfers tr
  WHERE tr.block_date >= DATE '2026-04-01'
    AND tr.blockchain IN ('base','arbitrum','optimism','polygon','avalanche_c','ethereum','arc')
    AND tr.symbol = 'USDC'
    AND (tr."from" IN (0x13bd0512365d12cd624be0dc1ffe753eb0d15c94, 0x9f90ae09197d5699a103595d6346d1a25775a613, 0x782edfa8fbfb075f500cd01a8f211815fd0998de, 0xe1d52fe2fa4e2d158d8e08eaebf938ad4b6e973c, 0x2b472d9d43887c447a793dfc78ded96a1e9b7899, 0xe9f22286a19ef6a0d8a73328f0494035b4bf05c9, 0x598ce4ac34cad18e0b0d58735ba1be0c4ccb5329, 0xee8100b30684aec3b793da0884fbcaa256e96dd9, 0xf4d2095155d5370b537bdd697587d9eaa6fcada4, 0xf4d2095155d5370b537bdd697587d9eaa6fcada4, 0xbc015b8d7a860400621b2bc1bd8f062614e5998a, 0xb5842e4549406154e17a952a0911f7ee08cb085b, 0x04056ff0be4d2cc641f365b98f2e9578f072fd1e, 0x3941a067d68f386dc76f81d26f76a6053ff0790a, 0x0d90f53bf00c18e3fac732eb151740fe596f5457, 0x89e3c3b03f3a6b138c6b08a7eb58c8945fb2d633, 0x8658bd8576ffc1d827c927f858af056a47e564fa, 0x8658bd8576ffc1d827c927f858af056a47e564fa, 0xd9efdfcfe7cc6b4f988d1af7e833bd5a60d6ee02, 0xb86e4d9bdce86d94c479b4ce4794152aed3d93ce, 0x8e2497dfc9e7dad595ad214da8ace0d69ac632ca, 0xecc82920b2bf64c85573ab1af57641c5418597e8, 0xecc82920b2bf64c85573ab1af57641c5418597e8, 0x3f62f83b10ff5abce4f3304e3f482a1691df4aab, 0xcd62b0963b554d354c670b33a2ecdfac4472bd53, 0xd8854db2d3793693d4d9a15d8037e59458caadd9, 0x376e3a544906d9686867b94eee5371b1811325f4, 0x5d83f02c82c387d6b8025aa484792fb74a4fea8e, 0x0e1e57c650725ff6edf87e3f595b5aad79f6b411, 0x06e2361e360be2fb64686e8c8cd22046821efdac, 0xbf8377bb2e8e52202f758c6cc2122dd0ab7119fa, 0x8b9742f6370cc6fc293f059de7777e93085a6401, 0xf2af457ce168175643d83c080b8aa9005f9f39b1, 0xb1ba64056a274c7372d34fcaaf17240a9a3ce3b8, 0x2bba27c3c984f51d6017cbe11ece1707e95177d6, 0x44809b5b1d2d35cf9d22e89557183e4444b9a5f6, 0x37ba366826a37abdcac8140949c4c8dc606e98a9, 0x5d8695c69167d248e6a530db17732f45fa686f2e, 0x889e82c4b6ca2c1ecfc309a8e77033ebf33d44d3, 0xfe5f6d90b8078fde5a0ef93a9115cb4ef6869c9a, 0xcbaed99c636dbe8fe4d9ac01a8d27d64ce486f49, 0xe125c6d7f8463ae22a7ede1efa48adb1ee23ccac, 0x05ab1807627dc87d3688f52544cb633fca0ead1f, 0x224fd1ced2449976a5f2ec71425b49f1b72c0ab2, 0x8a16aecb6eebce96dbc6fb2010110e28aff0e0f