-- One row per chain, each movement type its own COLUMN.
--
-- Shaped this way so the bar chart can put deposit and transfer side by side per chain: pick
-- deposit_usdc and transfer_usdc as the Y columns and they render as paired bars. The long form
-- (one row per chain AND type) could only do that via a group-by series, which draws all four
-- types or none -- there is no way to show just the two that matter to a reader.
--
-- COALESCE matters: a chain with no deposits returns NULL for that FILTER, and a NULL renders as
-- a MISSING bar rather than a zero one. A missing bar reads as "no data for this chain", which
-- is a different and wrong claim.
--
-- The bridge columns stay in the result even though the chart need not plot them -- the
-- per-chain table on the same query is where they are read.
SELECT
  chain,
  COALESCE(sum(usdc) FILTER (WHERE tx_type = 'deposit'),    0) AS deposit_usdc,
  COALESCE(sum(usdc) FILTER (WHERE tx_type = 'transfer'),   0) AS transfer_usdc,
  COALESCE(sum(usdc) FILTER (WHERE tx_type = 'bridge_in'),  0) AS bridge_in_usdc,
  COALESCE(sum(usdc) FILTER (WHERE tx_type = 'bridge_out'), 0) AS bridge_out_usdc,
  sum(usdc)                                                    AS total_usdc,
  count(*) FILTER (WHERE tx_type = 'deposit')                  AS deposit_txs,
  count(*) FILTER (WHERE tx_type = 'transfer')                 AS transfer_txs,
  count(*)                                                     AS transactions
FROM (
  SELECT chain, usdc, tx_type FROM evm
  UNION ALL
  SELECT chain, usdc, tx_type FROM stellar
)
WHERE tx_type <> 'fee'
GROUP BY 1
ORDER BY total_usdc DESC
